  "implementation": "def solve(case):\\n    if not isinstance(case, dict) or 'payload' not in case:\\n        raise ValueError('Invalid case: missing payload')\\n    payload = case['payload']\\n    if 'threshold' not in payload or 'calls' not in payload:\\n        raise ValueError('Invalid payload: missing threshold or calls')\\n    threshold = payload['threshold']\\n    calls = payload['calls']\\n    if not isinstance(calls, list):\\n        raise ValueError('calls must be a list')\\n    diagnostics = []\\n    accepted = []\\n    for call in calls:\\n        if not isinstance(call, dict):\\n            raise ValueError('each call must be a dict')\\n        required = ['call_id', 'loss_without_call', 'loss_with_call', 'prediction_tokens', 'parseable']\\n        for key in required:\\n            if key not in call:\\n                raise ValueError(f'Missing field {key} in call')\\n        call_id = call['call_id']\\n        loss_without = call['loss_without_call']\\n        loss_with = call['loss_with_call']\\n        tokens = call['prediction_tokens']\\n        parseable = call['parseable']\\n        if not isinstance(tokens, int) or tokens < 1:\\n            raise ValueError('prediction_tokens must be positive integer')\\n        gain = loss_without - loss_with\\n        normalized_gain = gain / tokens\\n        diag = {\\n            'call_id': call_id,\\n            'normalized_weight': round(normalized_gain, 6),\\n            'stronger_counterfactual': round(gain, 6)\\n        }\\n        diagnostics.append(diag)\\n        if parseable and normalized_gain >= threshold:\\n            accepted.append(call_id)\\n    return {\\n        'accepted_call_ids': accepted,\\n        'diagnostics': diagnostics\\n    }"
}
